ALTER TABLE "turnstile"."access_audit" DROP CONSTRAINT "access_audit_action";--> statement-breakpoint
ALTER TABLE "turnstile"."access_command_receipt" DROP CONSTRAINT "access_receipt_operation";--> statement-breakpoint
ALTER TABLE "turnstile"."access_command_receipt" ADD COLUMN "scope_parent_id" uuid;--> statement-breakpoint
ALTER TABLE "turnstile"."access_command_receipt" ADD COLUMN "organization_revision_after" integer;--> statement-breakpoint
ALTER TABLE "turnstile"."access_command_receipt" ADD COLUMN "access_revision_after" integer;--> statement-breakpoint
ALTER TABLE "turnstile"."access_audit" ADD CONSTRAINT "access_audit_action" CHECK ("turnstile"."access_audit"."action" IN ('legacy_imported','legacy_replaced','legacy_retired','administrator_bootstrapped','administrator_handed_over','member_assignments_changed','member_suspended','member_reactivated','role_created','role_details_changed','role_permissions_changed','role_deleted','unit_coverage_changed'));--> statement-breakpoint
ALTER TABLE "turnstile"."access_command_receipt" ADD CONSTRAINT "access_receipt_structure_revisions" CHECK (("turnstile"."access_command_receipt"."organization_revision_after" IS NULL AND "turnstile"."access_command_receipt"."access_revision_after" IS NULL) OR ("turnstile"."access_command_receipt"."operation" IN ('unit.create','unit.rename','unit.delete','unit.move') AND "turnstile"."access_command_receipt"."organization_revision_after" IS NOT NULL AND "turnstile"."access_command_receipt"."access_revision_after" IS NOT NULL AND "turnstile"."access_command_receipt"."organization_revision_after" >= 0 AND "turnstile"."access_command_receipt"."access_revision_after" >= 0));--> statement-breakpoint
ALTER TABLE "turnstile"."access_command_receipt" ADD CONSTRAINT "access_receipt_operation" CHECK ("turnstile"."access_command_receipt"."operation" IN ('legacy.replace','legacy.retire','administrator.bootstrap','administrator.handover','member.assignments','member.suspend','member.reactivate','role.create','role.patch','role.delete','invitation.issue','invitation.resend','invitation.cancel','invitation.reapprove','unit.create','unit.rename','unit.delete','unit.move'));